mapper.update:
update cere_shop_product
set shelve_state = 0, update_time = NOW()
where shop_id = #{shopId}

update cere_shop_product
set brand_id = null
where brand_id = #{brandId}

mapper.select:
SELECT a.shop_id, d.shop_name, a.product_id, a.product_name, x.users, d.shop_logo, IF( h.image IS NULL OR h.image = '', c.product_image, h.image ) image, b.price, b.sku_id, b.original_price, IF(f.number IS NULL, 0, f.number) number, b.stock_number from cere_shop_product a LEFT JOIN ( SELECT a.product_id, a.price, a.sku_id, a.original_price, a.stock_number from cere_product_sku a, cere_shop_product b where a.product_id = b.product_id GROUP BY a.product_id ) b ON a.product_id = b.product_id LEFT JOIN ( SELECT a.product_id, a.product_image from cere_product_image a, cere_shop_product b where a.product_id = b.product_id GROUP BY a.product_id ) c ON a.product_id = c.product_id LEFT JOIN cere_platform_shop d ON a.shop_id = d.shop_id LEFT JOIN cere_product_classify e ON a.classify_id = e.classify_id LEFT JOIN ( SELECT SUM(number) number, sku_id, order_id from cere_order_product GROUP BY sku_id ) f ON b.sku_id = f.sku_id LEFT JOIN cere_shop_order g ON f.order_id = g.order_id and g.state IN(2, 3, 4) LEFT JOIN ( SELECT a.sku_id, a.image from cere_sku_name a, cere_product_sku b where a.sku_id = b.sku_id LIMIT 1 ) h ON b.sku_id = h.sku_id LEFT JOIN ( SELECT COUNT(a.buyer_user_id) users, a.product_id FROM ( SELECT b.buyer_user_id, a.product_id FROM cere_order_product a, cere_shop_order b where a.order_id = b.order_id and b.state IN(2, 3, 4) GROUP BY a.product_id, b.buyer_user_id ) a GROUP BY a.product_id ) x ON a.product_id = x.product_id where a.shelve_state = 1 and d.state = 1
and a.shop_id=#{shopId}
and (d.shop_name like concat('%',#{search},'%') OR a.product_id like concat('%',#{search},'%') OR a.product_name like concat('%',#{search},'%'))
and a.shelve_state=#{shelveState}
and a.classify_id1 = #{classifyId}
and a.classify_id2 = #{classifyId}
and a.classify_id3 = #{classifyId}
and ( a.classify_id1 = #{classifyId} OR a.classify_id2 = #{classifyId} OR a.classify_id3 = #{classifyId} )
and a.product_id IN(
#{id}
)

SELECT
a.product_id,a.product_name,a.shop_id,e.shop_name,a.shelve_state,a.fictitious_number,a.create_time,c.stock_number,
concat('￥', a.min_price, '~￥', a.max_price) sectionPrice,a.product_image AS image
FROM cere_shop_product a INNER JOIN cere_platform_shop e ON a.shop_id = e.shop_id
LEFT JOIN (
SELECT sku.product_id, SUM(sku.stock_number) AS stock_number FROM cere_product_sku sku GROUP BY sku.product_id
) c ON c.product_id = a.product_id


        and e.shop_name like concat('%',#{shopName},'%')


        and a.product_id like concat('%',#{productId},'%')


        and a.product_name like concat('%',#{productName},'%')


        and a.create_time>=#{startTime} and a.create_time<=#{endTime}


        and a.shelve_state=#{shelveState}





                    and a.classify_id1 = #{classifyId}


                    and a.classify_id2 = #{classifyId}


                    and a.classify_id3 = #{classifyId}



                and (
                a.classify_id1 = #{classifyId}
                OR a.classify_id2 = #{classifyId}
                OR a.classify_id3 = #{classifyId}
                )




ORDER by a.update_time DESC,a.create_time DESC

select a.sku_id, a.need, a.sku_name, a.sku_value, a.image
from cere_sku_name a join cere_product_sku b on a.sku_id = b.sku_id
where b.product_id = #{productId}

SELECT d.shop_id, d.shop_name, d.shop_logo, a.product_id, b.product_name, a.activity_type, if(a.activity_type = 1, a.activity_id, 0) as shopGroupWorkId, if(a.activity_type = 2, a.activity_id, 0) as shopSeckillId, if(a.activity_type = 3, a.activity_id, 0) as shopDiscountId, a.sales_user_count + fictitious_number as users, c.product_image as image, a.start_time, a.end_time, a.state, a.if_enable - 1 as ifEnable, a.enable_time, a.cur_price as price, a.cur_original_price original_price, a.sku_id, n.stock_number,
a.sales_volume as number
a.product_sales_volume as number
FROM cere_sku_member_real_info a JOIN cere_shop_product b on b.product_id = a.product_id JOIN cere_product_image c on c.product_id = a.product_id JOIN cere_platform_shop d ON b.shop_id = d.shop_id JOIN cere_product_sku n ON a.sku_id = n.sku_id JOIN cere_recommend_product crp on crp.product_id = a.product_id
and crp.recommend_type = #{recommendType}
JOIN cere_product_classify e ON b.classify_id = e.classify_id
where a.member_level_id = 0 and b.shelve_state = 1 and d.state = 1
and a.activity_type = 1
and a.activity_type = 2
and a.activity_type = 3
and b.shop_id = #{shopId}
and (d.shop_name like concat('%', #{search}, '%') OR a.product_id like concat('%', #{search}, '%') OR b.product_name like concat('%', #{search}, '%'))
and b.classify_id1 = #{classifyId}
and b.classify_id2 = #{classifyId}
and b.classify_id3 = #{classifyId}
and ( b.classify_id1 = #{classifyId} OR b.classify_id2 = #{classifyId} OR b.classify_id3 = #{classifyId} )
and a.product_id IN(
#{id}
)
GROUP BY a.product_id ORDER BY a.update_time DESC, b.update_time DESC
